CREATE OR REPLACE VIEW FLEET_APP.ROUTE_OPTIMIZATION.VW_FLEET_CURRENT
  COMMENT='{"origin":"sf_sit-is-fleet","name":"oss-install-fleet-apps","version":{"major":1,"minor":0},"attributes":{"is_quickstart":1,"source":"sql"}}' AS
SELECT VEHICLE_ID, REGION, VEHICLE_TYPE, HOME_LOCATION_ID,
       DRIVER_PROFILE, ORS_PROFILE, OPERATING_MODE, JOB_ID
FROM SYNTHETIC_DATASETS.UNIFIED.V_DIM_FLEET_CURRENT
WHERE VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.ROUTE_OPTIMIZATION.CONFIG LIMIT 1)
  AND REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.ROUTE_OPTIMIZATION.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.ROUTE_OPTIMIZATION.VW_TRIPS_CURRENT
